    .pricing-card::before {
      content: "";
      position: absolute;

      top: -1px;
      left: -1px;

      width: calc(100% + 3px);
      height: 3px;

      background: linear-gradient(
        90deg,
        #d4af37 0%,
        #0e4677 28%,
        #007f7b 48%,
        #7a237f 72%,
        #d4af37 100%
      );

      background-size: 300% 100%;

      animation: vdPricingTopBorder 5s linear infinite;

      z-index: 5;
      pointer-events: none;
    }


    /* ---------------------------------------------------------
      ANIMATED LEFT BORDER
      --------------------------------------------------------- */

    .pricing-card::after {
      content: "";
      position: absolute;

      top: -1px;
      left: -1px;

      width: 3px;
      height: calc(100% + 3px);

      background: linear-gradient(
        180deg,
        #0e4677 0%,
        #007f7b 28%,
        #d4af37 52%,
        #7a237f 76%,
        #0e4677 100%
      );

      background-size: 100% 300%;

      animation: vdPricingLeftBorder 5s linear infinite;

      z-index: 5;
      pointer-events: none;
