        /* ===== Overlay ===== */
        body.vd-locked {
          overflow: hidden;
        }

        .vd-popup-overlay {
          position: fixed;
          inset: 0;
          background: rgba(10, 30, 20, 0.55);
          display: none;
          align-items: center;
          justify-content: center;
          z-index: 9999;
          opacity: 0;
        }

        .vd-popup-overlay.is-active {
          display: flex;
          opacity: 1;
          animation: vdFadeIn .3s ease forwards;
        }

        .vd-popup-overlay.is-closing {
          animation: vdFadeOut .9s ease forwards;
        }

        @keyframes vdFadeIn {
          from {
            opacity: 0;
          }

          to {
            opacity: 1;
          }
        }

        @keyframes vdFadeOut {
          from {
            opacity: 1;
          }

          to {
            opacity: 0;
          }
        }

        /* ===== Wrapper holds the card + decorative shapes ===== */
        .vd-popup-wrap {
          position: relative;
          width: min(620px, 92vw);
          display: flex;
          justify-content: center;
        }

        /* organic blob — the only thing that drifts with the cursor */
        .vd-popup-shape-big {
          position: absolute;
          top: 50%;
          left: 60%;
          width: 560px;
          height: 560px;
          max-width: 110vw;
          max-height: 110vw;
          background: var(--tj-color-theme-primary);
          border-radius: 62% 38% 51% 49% / 45% 55% 43% 57%;
          transform: translate(-50%, -50%);
          z-index: 0;
          pointer-events: none;
          transition: transform .18s ease-out;
          will-change: transform;
          animation: vdBlobMorph 14s ease-in-out infinite;
        }

        @keyframes vdBlobMorph {

          0%,
          100% {
            border-radius: 62% 38% 51% 49% / 45% 55% 43% 57%;
          }

          33% {
            border-radius: 45% 55% 62% 38% / 55% 40% 60% 45%;
          }

          66% {
            border-radius: 56% 44% 38% 62% / 40% 62% 38% 60%;
          }
        }

        .vd-popup-shape-small {
          position: absolute;
          top: -24px;
          right: 50px;
          width: 52px;
          height: 52px;
          background: var(--tj-color-theme-primary);
          border-radius: 50%;
          z-index: 2;
          pointer-events: none;
          transition: transform .18s ease-out;
          will-change: transform;
        }

        /* ===== Card ===== */
        .vd-popup-card {
          position: relative;
          background: #ffffff;
          width: 100%;
          max-height: 90vh;
          overflow: auto;
          border-radius: 16px;
          box-shadow: 0 30px 60px rgba(0, 0, 0, 0.25);
          padding: 44px 44px 36px;
          transform: translate3d(0, 24px, 0) scale(.96);
          opacity: 0;
          z-index: 1;
        }

        .vd-popup-overlay.is-active .vd-popup-card {
          animation: vdCardIn .38s cubic-bezier(.2, .8, .3, 1) forwards;
        }

        .vd-popup-overlay.is-closing .vd-popup-card {
          animation: vdCardOut .9s cubic-bezier(.6, 0, .85, .15) forwards;
          transform-origin: 50% 50%;
        }

        @keyframes vdCardIn {
          from {
            opacity: 0;
            transform: translate3d(0, 24px, 0) scale(.96);
          }

          to {
            opacity: 1;
            transform: translate3d(0, 0, 0) scale(1);
          }
        }

        /* anticlockwise clock-sweep close, slow */
        @keyframes vdCardOut {
          0% {
            opacity: 1;
            transform: rotate(0deg) scale(1) translate3d(0, 0, 0);
          }

          60% {
            opacity: 1;
            transform: rotate(-90deg) scale(.55) translate3d(0, 10px, 0);
          }

          100% {
            opacity: 0;
            transform: rotate(-90deg) scale(.1) translate3d(0, 20px, 0);
          }
        }

