        }


        /* === Vidhitra hero slide-nav: labeled tabs + progress fill === */

        .vd-slide-nav {
          position: absolute;
          left: 0;
          right: 0;
          bottom: 30px;
          z-index: 5;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 20px;
          padding: 0 40px;
        }

        .vd-slide-nav-arrow {
          flex: 0 0 auto;
          width: 40px;
          height: 40px;
          border-radius: 50%;
          border: 1px solid rgba(247, 245, 241, 0.35);
