      .vd-slide-tabs {
        display: flex;
        align-items: stretch;
        gap: 0;

        width: min(1450px, 90vw);
        max-width: 1450px;

        overflow: visible;
      }

        .vd-slide-tabs::-webkit-scrollbar {
          display: none;
        }

        .vd-slide-tab {
          position: relative;
          flex: 1 1 0;
          min-width: 240px;
          background: transparent;
          border: none;
          /* border-left: 1px solid rgba(247, 245, 241, 0.25); */
          border-left: none !important;
          padding: 0 18px 14px;
          text-align: left;
          cursor: pointer;
        }

        .vd-slide-tab:first-child {
          border-left: none;
        }

      .vd-tab-label {
        display: block;
        text-align: center;
        font-family: var(--tj-ff-heading, 'Libre Franklin', serif);
        font-size: 18px;
        font-weight: 600;
        letter-spacing: 0.03em;

        color: rgba(247,245,241,0.72) !important;

        white-space: nowrap;
        overflow: visible;
        text-overflow: unset;

        margin-bottom: 10px;

        transition:
          color 0.35s ease,
          transform 0.35s ease,
          text-shadow 0.35s ease;
      }

      .vd-slide-tab.is-active .vd-tab-label {
        color: #C6A15B !important;
        transform: translateY(-2px);

        text-shadow:
          0 0 10px rgba(198,161,91,0.25);
      }

        .vd-tab-progress {
          display: block;
          width: 100%;
          height: 2px;
          background: rgba(247, 245, 241, 0.2);
          border-radius: 2px;
          overflow: hidden;
        }

        .vd-tab-progress-fill {
          display: block;
          height: 100%;
          width: 0%;
          background: var(--tj-color-gold, #C6A15B);
          border-radius: 2px;
        }


        .vd-tab-progress {
        display: block;
        width: 100%;
        height: 3px;

        background: rgba(198,161,91,0.18);
        border-radius: 50px;
        overflow: hidden;

        margin-top: 4px;
      }

      .vd-tab-progress-fill {
        display: block;
        height: 100%;
        width: 0%;

        background: linear-gradient(
          90deg,
          #9E7534,
          #C6A15B,
          #F3D58A,
          #C6A15B
        );

        background-size: 200% 100%;
        border-radius: 50px;

        box-shadow:
          0 0 8px rgba(198,161,91,0.55);
      }

        /* Active tab state */
        .vd-slide-tab.is-active .vd-tab-label {
          color: var(--tj-color-common-white, #FFFFFF);
        }

        /* Progress fill animates only on the active tab — JS toggles this class
          and restarts the animation each time the slide changes */
        .vd-slide-tab.is-active .vd-tab-progress-fill.is-filling {
          animation: vd-tab-fill linear forwards;
          animation-duration: var(--vd-autoplay-duration, 5000ms);
          /* matches Swiper autoplay delay: 5000 in main.js */
        }

        @keyframes vd-tab-fill {
          from {
            width: 0%;
          }

          to {
            width: 100%;
          }
        }

        /* Completed slides (already viewed in this pass) show a full gold line, no animation */
        .vd-slide-tab.is-complete .vd-tab-progress-fill {
          width: 100%;
          animation: none;
        }

