        /* === Vidhitra FAQ — spotlight split-panel === */

        .tj-faq-section {
          padding: 120px 0;
          background: var(--tj-color-common-white, #FFFFFF);
        }

        .tj-faq-spotlight {
          display: grid;
          grid-template-columns: 5fr 7fr;
          gap: 60px;
          margin-top: 60px;
          align-items: start;
        }

        /* --- Left: question list --- */
        .tj-faq-list {
          display: flex;
          flex-direction: column;
        }

        .tj-faq-q {
          display: flex;
          align-items: baseline;
          gap: 18px;
