        .vd-stat-circle {
        position: relative;
        width: 100%;
        max-width: 480px;
        height: 480px;
        margin-left: auto;
      }

      /* the ring itself — a circle, half of it bleeding off the right edge
        of the viewport so it reads as a "half circle" motif */
      .vd-stat-circle-ring {
        position: absolute;
        top: 50%;
        right: -140px;
        transform: translateY(-50%);
        width: 420px;
        height: 420px;
        border: none;
        border-radius: 50%;
      }

      .vd-stat-dot {
        position: absolute;
        top: 50%;
        left: 50%;
        width: 14px;
        height: 14px;
        margin: -7px 0 0 -7px;
        border-radius: 50%;
        background: var(--tj-color-gold, #C6A15B);
        transition: background 0.4s ease, transform 0.4s ease, box-shadow 0.4s ease;
      }

      .vd-stat-dot.active {
        background: var(--tj-color-theme-primary, #005c59);
        transform: scale(1.6);
        box-shadow: 0 0 0 6px rgba(0, 92, 89, 0.12);
      }

      /* label block — only the active one is visible; others are display:none
        until JS swaps the .active class */
      .vd-stat-circle-labels {
        position: absolute;
        top: 50%;
        left: 0;
        transform: translateY(-50%);
        max-width: 260px;
      }

      .vd-stat-circle-label {
        display: none;
        flex-direction: column;
        gap: 6px;
        animation: vdStatFade 0.5s ease;
      }

      .vd-stat-circle-label.active {
        display: flex;
      }

      @keyframes vdStatFade {
        from { opacity: 0; transform: translateY(10px); }
        to   { opacity: 1; transform: translateY(0); }
      }

      .vd-stat-circle-value {
        font-family: var(--tj-ff-heading, 'Libre Franklin', serif);
        font-size: 35px;
        font-weight: 800;
        color: var(--tj-color-theme-dark, #3A1837);
        line-height: 1.1;
      }

      .vd-stat-circle-name {
        font-size: 13px;
        font-weight: 600;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--tj-color-text-body-2, #6B6B6B);
      }

      @media (max-width: 991px) {
        .vd-stat-circle { height: 360px; }
        .vd-stat-circle-ring { width: 320px; height: 320px; right: -110px; }
      }

      @media (max-width: 575px) {
        .vd-stat-circle { height: 300px; margin: 0 auto; }
        .vd-stat-circle-ring { width: 300px; height: 3000px; right: -90px; }
        .vd-stat-circle-value { font-size: 30px; }
      }


      /* progress arc sits exactly over the existing border ring */
      .vd-progress-ring {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        transform: rotate(-90deg); /* start the draw from 12 o'clock */
        pointer-events: none;
      }

      .vd-progress-ring-bg {
        fill: none;
        stroke: rgba(58, 24, 55, 0.08); /* quiet track in your ink color, not grey */
        stroke-width: 1.5;
      }

      .vd-progress-ring-fill {
        fill: none;
        stroke: var(--tj-color-gold, #C6A15B);
        stroke-width: 2;
        stroke-linecap: round;
        stroke-dasharray: 1281.8;
        stroke-dashoffset: 1281.8;
      }

      .vd-stat-circle-image {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 228px;
        height: 228px;
        border-radius: 50%;
        overflow: hidden;
        z-index: 1;
        box-shadow:
          0 20px 45px -12px rgba(58, 24, 55, 0.35), /* lift off the page */
          0 0 0 6px rgba(255, 255, 255, 0.9);        /* a breathing gap before the gold ring */
      }

      .vd-stat-circle-image img {
        position: absolute;
        top: 0; left: 0;
        width: 100%; height: 100%;
        object-fit: cover;
        opacity: 0;
        transition: opacity 0.6s ease;
        /* remove the box-shadow from here entirely — it can never render */
      }

      .vd-stat-circle-image img.active { opacity: 1; }
      .vd-stat-circle-backdrop {
        position: absolute;
        top: 50%;
        left: 50%;
        font-family: var(--tj-ff-heading, 'Libre Franklin', serif);
        font-weight: 900;
        font-size: 96px;
        line-height: 1;
        color: rgba(0, 92, 89, 0.10);
        white-space: nowrap;
        z-index: 0;
        opacity: 0;
        pointer-events: none;

        /* idle state: shifted right, off to the side */
        transform: translate(-50%, -50%) translateX(50px);
        transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
      }

      .vd-stat-circle-backdrop.active {
        opacity: 1;
        /* active state: settled into center — this is what creates the slide */
        transform: translate(-50%, -50%) translateX(0);
      }

      @media (max-width: 991px) { .vd-stat-circle-image { width: 96px; height: 96px; } }
      @media (max-width: 575px) { .vd-stat-circle-image { width: 170px; height: 170px; } }


      .vd-stat-col {
        position: relative; /* strip needs a positioned ancestor to span against */
        min-height: 480px; 
      }

      @media (max-width: 991px) {
        .vd-stat-col { min-height: 360px; }
      }

      @media (max-width: 575px) {
        .vd-stat-col { min-height: 300px; }
      }

      .vd-stat-strip {
        position: absolute;
        top: 50%;
        left: 0;
        width: 100%;          /* spans from label all the way to behind the image */
        height: 85px;
        transform: translateY(-50%) scaleX(0);
        transform-origin: right center; /* pinned at the image side, grows leftward */
        background: linear-gradient(90deg, rgb(198 161 91 / 37%), rgb(0 92 89 / 38%));
        border-radius: 4px;
        z-index: 0;            /* sits behind the text */
        pointer-events: none;
      }

      .vd-stat-strip.sweep {
        animation: vdStripSweep 0.7s cubic-bezier(0.16, 1, 0.3, 1) forwards;
      }

      @keyframes vdStripSweep {
        from { transform: translateY(-50%) scaleX(0); }
        to   { transform: translateY(-50%) scaleX(1); }
      }

      /* make sure the label text renders ABOVE the strip, not under it */
      .vd-stat-circle-labels {
        position: relative;
        z-index: 1;
      }

      @media (prefers-reduced-motion: reduce) {
        .vd-stat-strip.sweep { animation: none; transform: translateY(-50%) scaleX(1); }
      }


      .vd-stat-backdrop-panel {
        position: absolute;
        top: 50%;
        right: 0;                    /* flush to the container's right edge */
        transform: translateY(-50%);
        width: 55%;                  /* reaches roughly to the circle's center */
        height: 340px;
        background: linear-gradient(135deg, rgba(0, 92, 89, 0.06), rgba(198, 161, 91, 0.10));
        border-radius: 24px 0 0 24px; /* soft on the inner edge, flat against the screen edge */
        z-index: -2;                  /* behind the ring, glow, strip, everything */
        pointer-events: none;
      }

      @media (max-width: 991px) {
        .vd-stat-backdrop-panel { width: 60%; height: 260px; }
      }

      @media (max-width: 575px) {
        .vd-stat-backdrop-panel { display: none; } /* the ring is already centered/small here — a panel would just crowd it */
