      /* =========================================================
      WHO WE ARE — image pillars + animated backdrop
      Append to main.css. Uses only existing :root variables.
      ========================================================= */

    /* Section fills the pinned viewport so it never feels empty.
      Header is absolute, so top padding clears it. */
    .h6-about-section.vd-about {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      padding: 110px 0 60px;
      isolation: isolate;
    }
    .h6-about-section.vd-about > .container { width: 100%; }

    /* ---------- animated backdrop ---------- */
    .vd-about-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(70px);
      opacity: .16;
      z-index: -1;
      pointer-events: none;
      animation: vdAboutFloat 12s ease-in-out infinite;
    }
    .vd-about-blob--a {
      width: 420px; height: 420px;
      top: -120px; left: -140px;
      background: var(--tj-color-theme-primary);
    }
    .vd-about-blob--b {
      width: 360px; height: 360px;
      bottom: -110px; right: -90px;
      background: var(--tj-color-gold);
      animation-delay: -5s;
    }
    .vd-about-dots {
      position: absolute;
      top: 90px; left: 0;
      width: 46%; height: 260px;
      z-index: -1;
      pointer-events: none;
      background-image: radial-gradient(var(--tj-color-border-3) 1.5px, transparent 1.6px);
      background-size: 22px 22px;
      -webkit-mask-image: linear-gradient(90deg, #000, transparent);
              mask-image: linear-gradient(90deg, #000, transparent);
    }
    @keyframes vdAboutFloat {
      0%, 100% { transform: translate(0, 0) scale(1); }
      50%      { transform: translate(30px, -24px) scale(1.08); }
    }

    /* ---------- text ---------- */
    .vd-about-left .sec-heading { margin-bottom: 22px; }

    .vd-about-lead {
      font-family: var(--tj-ff-heading);
      font-size: 19px;
      font-style: italic;
      font-weight: var(--tj-fw-medium);
      line-height: 1.55;
      color: var(--tj-color-heading-primary);
      border-left: 3px solid var(--tj-color-gold);
      padding-left: 18px;
      margin-bottom: 16px;
    }
    .vd-about-p {
      font-size: 15px;
      line-height: 1.7;
      color: var(--tj-color-text-body);
      margin-bottom: 10px;
      max-width: 760px;
    }

    /* text reveal (uses the .is-inview your existing script already toggles) */
    .vd-about-lead,
    .vd-about-p {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity .7s cubic-bezier(.16, 1, .3, 1), transform .7s cubic-bezier(.16, 1, .3, 1);
    }
    .vd-about-left.is-inview .vd-about-lead { opacity: 1; transform: none; transition-delay: .15s; }
    .vd-about-left.is-inview .vd-about-p:nth-of-type(2) { opacity: 1; transform: none; transition-delay: .25s; }
    .vd-about-left.is-inview .vd-about-p:nth-of-type(3) { opacity: 1; transform: none; transition-delay: .35s; }
    .vd-about-left.is-inview .vd-about-p:nth-of-type(4) { opacity: 1; transform: none; transition-delay: .45s; }

    /* ---------- image pillars ---------- */
    .vd-about-pillars {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 14px;
      margin-top: 26px;
    }
    .vd-pillar {
      position: relative;
      display: block;
      height: 150px;
      border-radius: 14px;
      overflow: hidden;
      isolation: isolate;
      box-shadow: 0 10px 26px rgba(58, 24, 55, .12);

      opacity: 0;
      transform: translateY(30px) scale(.95);
      transition: opacity .7s cubic-bezier(.16, 1, .3, 1),
                  transform .7s cubic-bezier(.16, 1, .3, 1),
                  box-shadow .35s ease;
    }
    .vd-about-left.is-inview .vd-pillar { opacity: 1; transform: none; }
    .vd-about-left.is-inview .vd-pillar:nth-child(1) { transition-delay: .55s; }
    .vd-about-left.is-inview .vd-pillar:nth-child(2) { transition-delay: .65s; }
    .vd-about-left.is-inview .vd-pillar:nth-child(3) { transition-delay: .75s; }
    .vd-about-left.is-inview .vd-pillar:nth-child(4) { transition-delay: .85s; }

    .vd-pillar:hover {
      transform: translateY(-6px);
      box-shadow: 0 18px 36px rgba(58, 24, 55, .24);
      transition-delay: 0s;
    }

    /* slow ken-burns drift so the images feel alive */
    .vd-pillar img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      z-index: -2;
      animation: vdPillarDrift 14s ease-in-out infinite alternate;
      transition: filter .4s ease;
    }
    .vd-pillar:nth-child(2) img { animation-delay: -3s; }
    .vd-pillar:nth-child(3) img { animation-delay: -6s; }
    .vd-pillar:nth-child(4) img { animation-delay: -9s; }
    .vd-pillar:hover img { filter: saturate(1.15) brightness(1.05); }
    @keyframes vdPillarDrift {
      from { transform: scale(1.02) translate(0, 0); }
      to   { transform: scale(1.14) translate(-2%, -2%); }
    }

    /* brand gradient over the photo */
    .vd-pillar::after {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      background: linear-gradient(to top, var(--tj-color-border-1) 0%, transparent 72%);
      opacity: .88;
      transition: opacity .35s ease;
    }
    .vd-pillar:hover::after { opacity: .7; }

    /* gold bar that grows on hover */
    .vd-pillar::before {
      content: "";
      position: absolute;
      left: 0; bottom: 0;
      height: 3px; width: 0;
      background: var(--tj-color-gold);
      z-index: 2;
      transition: width .45s ease;
    }
    .vd-pillar:hover::before { width: 100%; }

    .vd-pillar-label {
      position: absolute;
      left: 12px; right: 12px; bottom: 12px;
      display: flex;
      align-items: center;
      gap: 9px;
      font-family: var(--tj-ff-heading);
      font-size: 13.5px;
      font-weight: var(--tj-fw-bold);
      line-height: 1.25;
      color: var(--tj-color-common-white);
    }
    .vd-pillar-label i {
      flex: 0 0 30px;
      width: 30px; height: 30px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      color: var(--tj-color-border-1);
      background: var(--tj-color-gold);
      transition: transform .35s ease;
    }
    .vd-pillar:hover .vd-pillar-label i { transform: rotate(-8deg) scale(1.1); }

    .vd-pillar-go {
      position: absolute;
      top: 10px; right: 10px;
      width: 28px; height: 28px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      color: var(--tj-color-common-white);
      background: var(--tj-color-theme-primary);
      opacity: 0;
      transform: translate(-6px, 6px);
      transition: opacity .3s ease, transform .3s ease;
    }
    .vd-pillar:hover .vd-pillar-go { opacity: 1; transform: none; }

    /* ---------- responsive ---------- */
    @media (max-width: 991px) {
      .h6-about-section.vd-about { min-height: 0; padding: 70px 0 50px; }
      .vd-about-pillars { grid-template-columns: repeat(2, 1fr); }
      .vd-pillar { height: 130px; }
