    }

    /* ---------- reduced motion ---------- */
    @media (prefers-reduced-motion: reduce) {
      .vd-about-blob,
      .vd-pillar img { animation: none !important; }
      .vd-about-lead,
      .vd-about-p,
      .vd-pillar { opacity: 1 !important; transform: none !important; transition: none !important; }
    }

