      background:
        radial-gradient(circle at 10% 15%, rgba(0, 92, 89, .07), transparent 40%),
        radial-gradient(circle at 60% 95%, rgba(154, 0, 100, .06), transparent 45%),
        linear-gradient(180deg, #FFFFFF 0%, var(--tj-color-theme-bg) 100%);
    }

    /* Big outlined watermark behind the text */
    .vd-about-watermark {
      position: absolute;
