    /* ---------- Right side (desktop only) ---------- */
    @media (min-width: 992px) {

      /* Half-circle: rich brand gradient instead of washed-out grey */
      .vd-stat-halfcircle {
        background:
          linear-gradient(135deg,
            rgba(154, 0, 100, .82) 0%,
            rgba(58, 24, 55, .78) 45%,
            rgba(0, 92, 89, .78) 100%),
