        box-shadow:
          inset 0 0 0 1px rgba(198, 161, 91, .35),
          0 40px 90px -30px rgba(58, 24, 55, .45);
      }
      @keyframes vdHalfIn {
        from { opacity: 0; transform: translateY(-50%) scale(.88); }
        to   { opacity: 1; transform: translateY(-50%) scale(1); }
