      .vd-about-float-badge small {
        font-size: 12px;
        color: var(--tj-color-text-body-2);
      }
      @keyframes vdBadgeFloat {
        0%, 100% { transform: translateY(0); }
        50%      { transform: translateY(-10px); }
      }
    }

    @media (max-width: 991px) {
      .vd-about-float-badge { display: none; }
    }

