    /* reveal */
    .vd-who-stat,.vd-who-pillar{opacity:0;transform:translateY(24px)}
    .vd-who.is-inview .vd-who-stat,.vd-who.is-inview .vd-who-pillar{opacity:1;transform:none}
    .vd-who.is-inview .vd-who-stat:nth-child(2),.vd-who.is-inview .vd-who-pillar:nth-child(2){transition-delay:.12s}
    .vd-who.is-inview .vd-who-stat:nth-child(3),.vd-who.is-inview .vd-who-pillar:nth-child(3){transition-delay:.24s}
    .vd-who.is-inview .vd-who-stat:nth-child(4),.vd-who.is-inview .vd-who-pillar:nth-child(4){transition-delay:.36s}
