    @media(max-width:991px){.vd-who{padding:70px 0}.vd-who-pillars{grid-template-columns:1fr 1fr;margin-top:50px}}
    @media(max-width:575px){.vd-who-pillars{grid-template-columns:1fr}.vd-who-num{font-size:36px}.vd-who-num-text{font-size:22px}}
