    /* Transparent background image for "Who We Are" */
    .vd-who::before{
      content:"";
      position:absolute;
      inset:0;
      background:url("../images/vidhitra/breadcrumbs/corporate.webp") center/cover no-repeat;
      opacity:0.20;                 /* 0.06 = very subtle, 0.15 = more visible */
      z-index:45;
      pointer-events:none;
    }

    /* soft cream wash on top so the image never overpowers the text */
    .vd-who::after{
      content:"";
      position:absolute;
      inset:0;
      background:linear-gradient(180deg, rgba(255,248,242,.85) 0%, rgba(255,248,242,.35) 50%, rgba(255,248,242,.9) 100%);
      z-index:0;
      pointer-events:none;
    }

    /* ===== Credentials — big value + black bar, wipe left → right ===== */
    .vd-cred{
      display:flex;
      flex-direction:column;
      gap:38px;
      padding:10px 0 10px 30px;
    }

    .vd-cred-item{ max-width:450px; }

    /* big value: fades in sliding from the left */
    .vd-cred-value{
      font-family:'Libre Franklin',sans-serif;
      font-size:clamp(44px,4.6vw,68px);
      font-weight:800;
      line-height:1;
      letter-spacing:-0.03em;
      color:#151515;
      margin-bottom:12px;

      opacity:0;
      transform:translateX(-46px);
      transition:opacity .8s cubic-bezier(.16,1,.3,1),
                transform .8s cubic-bezier(.16,1,.3,1);
    }

    /* black bar: wipes open left → right */
    .vd-cred-bar{
      background:#000;
      border-radius:4px;
      padding:10px 14px;
      clip-path:inset(0 100% 0 0);
      transition:clip-path .9s cubic-bezier(.65,0,.35,1);
    }

    /* bar text: fades in from the left after the bar opens */
    .vd-cred-bar span{
      display:block;
      font-size:19px;
      font-weight:500;
      color:#fff;
      opacity:0;
      transform:translateX(-22px);
      transition:opacity .6s ease, transform .6s cubic-bezier(.16,1,.3,1);
    }

    /* triggered by the existing .is-inview on .vd-who */
    .vd-who.is-inview .vd-cred-value{ opacity:1; transform:none; }
    .vd-who.is-inview .vd-cred-bar{ clip-path:inset(0 0 0 0); }
    .vd-who.is-inview .vd-cred-bar span{ opacity:1; transform:none; }

    /* stagger each item */
    .vd-who.is-inview .vd-cred-item:nth-child(1) .vd-cred-value{ transition-delay:.05s; }
    .vd-who.is-inview .vd-cred-item:nth-child(1) .vd-cred-bar{ transition-delay:.25s; }
    .vd-who.is-inview .vd-cred-item:nth-child(1) .vd-cred-bar span{ transition-delay:.75s; }

    .vd-who.is-inview .vd-cred-item:nth-child(2) .vd-cred-value{ transition-delay:.25s; }
    .vd-who.is-inview .vd-cred-item:nth-child(2) .vd-cred-bar{ transition-delay:.45s; }
    .vd-who.is-inview .vd-cred-item:nth-child(2) .vd-cred-bar span{ transition-delay:.95s; }

    .vd-who.is-inview .vd-cred-item:nth-child(3) .vd-cred-value{ transition-delay:.45s; }
    .vd-who.is-inview .vd-cred-item:nth-child(3) .vd-cred-bar{ transition-delay:.65s; }
    .vd-who.is-inview .vd-cred-item:nth-child(3) .vd-cred-bar span{ transition-delay:1.15s; }

    .vd-who.is-inview .vd-cred-item:nth-child(4) .vd-cred-value{ transition-delay:.65s; }
    .vd-who.is-inview .vd-cred-item:nth-child(4) .vd-cred-bar{ transition-delay:.85s; }
    .vd-who.is-inview .vd-cred-item:nth-child(4) .vd-cred-bar span{ transition-delay:1.35s; }

    @media(max-width:991px){
      .vd-cred{ padding-left:0; gap:30px; margin-top:10px; }
      .vd-cred-bar span{ font-size:17px; }
    }

    @media(prefers-reduced-motion:reduce){
      .vd-cred-value,.vd-cred-bar,.vd-cred-bar span{
        opacity:1!important; transform:none!important;
        clip-path:none!important; transition:none!important;
      }
    }

    /* ===== WHO WE ARE — site-wide consistency ===== */

    /* 1. FIX: image was above the content (z-index:45). Put it behind. */
    .vd-who::before{
      z-index:0;
      background:url("../images/vidhitra/breadcrumbs/bg-w.png") center/cover no-repeat;
      opacity:.28;
    }
    .vd-who::after{
