    }

    /* 3. Stats: same fonts + plum/gold gradient as the FAQ cards */
    .vd-cred-value{
      font-family:'Libre Franklin',sans-serif;
      font-size:clamp(38px,4vw,58px);
      font-weight:800;
      letter-spacing:-0.025em;
