      .vd-slide-tabs {
        display: flex;
        align-items: stretch;
        gap: 0;

        width: min(1450px, 90vw);
        max-width: 1450px;

        overflow: visible;
      }

        .vd-slide-tabs::-webkit-scrollbar {
          display: none;
        }

        .vd-slide-tab {
          position: relative;
          flex: 1 1 0;
          min-width: 240px;
          background: transparent;
          border: none;
          /* border-left: 1px solid rgba(247, 245, 241, 0.25); */
