        .vd-tab-progress {
          display: block;
          width: 100%;
          height: 2px;
          background: rgba(247, 245, 241, 0.2);
          border-radius: 2px;
          overflow: hidden;
        }

        .vd-tab-progress-fill {
          display: block;
          height: 100%;
          width: 0%;
