      /* Give each successive card a higher z-index so it visually covers
        the ones before it once both are pinned at the same scroll position. */
      .vd-stack-card:nth-child(1) { z-index: 1; }
      .vd-stack-card:nth-child(2) { z-index: 2; }
      .vd-stack-card:nth-child(3) { z-index: 3; }
      .vd-stack-card:nth-child(4) { z-index: 4; }
      .vd-stack-card:nth-child(5) { z-index: 5; }
      .vd-stack-card:nth-child(6) { z-index: 6; }
      .vd-stack-card:nth-child(7) { z-index: 7; }

      .vd-stack-inner {
        width: 100%;
        max-width: 1320px;
        margin: 0 auto;
        padding: 45px 60px;
        display: grid;
