      /* ---------- Right: image ---------- */
      .vd-stack-image {
        width: 100%;
        aspect-ratio: 4 / 3;
        border-radius: 8px;
        overflow: hidden;
      }

      .vd-stack-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
      }

      /* ---------- Responsive ---------- */
      @media (max-width: 991px) {
        .vd-stack-inner {
          grid-template-columns: 1fr;
          gap: 30px;
          padding: 50px 30px;
        }

        .vd-stack-card {
          min-height: auto;
          padding: 40px 0;
        }

        .vd-stack-image {
          order: -1;
          aspect-ratio: 16 / 9;
        }
      }

      @media (max-width: 575px) {
        .vd-stack-inner {
          padding: 40px 20px;
        }

        .vd-stack-title {
          font-size: 22px;
        }

