      .tj-header-area.header-duplicate {
        transition: left 1s cubic-bezier(0.785, 0.135, 0.15, 0.86),
                    width 1s cubic-bezier(0.785, 0.135, 0.15, 0.86),
                    transform 0.4s ease;
      }
      body.vd-menu-open .tj-header-area.header-duplicate {
        left: 310px;
        width: calc(100% - 310px);
      }

      /* No dark/blur overlay in push mode – you want to see the page */
      body.vd-menu-open .body-overlay {
        visibility: hidden !important;
      }

      /* Small screens: sidebar is 320px, so keep the old overlay behaviour */
      @media (max-width: 575px) {
        body.vd-menu-open { margin-left: 0; }
        body.vd-menu-open .tj-header-area.header-duplicate { left: 0; width: 100%; }
        body.vd-menu-open .body-overlay { visibility: visible !important; }
