    .tj-approach-number {
      position: relative;
      z-index: 2;
      isolation: isolate;
      transform-style: preserve-3d;
      backface-visibility: visible;
      -webkit-backface-visibility: visible;
      transform-origin: center center;
      transform: translateZ(0) rotateY(0deg);
      will-change: transform;
      box-shadow: none !important;
    }

    .js-ready .tj-approach-number {
      transform: translateZ(0) rotateY(-80deg);
    }

    .js-ready .tj-approach-item.in-view .tj-approach-number {
      animation: flipReverse 1.2s cubic-bezier(0.45, 0, 0.2, 1) forwards;
    }

    @keyframes flipReverse {
      0%   { transform: translateZ(0) rotateY(-80deg); box-shadow: none; opacity: 1; }
      50%  { opacity: 1; }
      99%  { box-shadow: none; opacity: 1; }
      100% { transform: translateZ(0) rotateY(0deg); box-shadow: 0 10px 25px rgba(0,0,0,0.25); opacity: 1; }
    }

    .tj-approach-number {
      overflow: visible;
    }

    .tj-approach-number span {
      display: inline-block;
      transform-style: preserve-3d;
      backface-visibility: hidden;
      -webkit-backface-visibility: hidden;
      transform-origin: center center;
      transform: translateX(0) translateZ(0) rotateY(0deg);
      opacity: 1;
      will-change: transform, opacity;
    }

    .js-ready .tj-approach-number span {
      transform: translateX(-100%) translateZ(0) rotateY(-120deg);
      opacity: 0;
    }

    .js-ready .tj-approach-item.in-view .tj-approach-number span {
      animation: digitFlip 1.4s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    }

    @keyframes digitFlip {
      0%   { transform: translateX(-100%) translateZ(0) rotateY(-120deg); opacity: 0; }
      18%  { opacity: 0; }
      28%  { opacity: 0.6; }
      40%  { transform: translateX(-55%) translateZ(0) rotateY(-75deg); opacity: 1; }
      62%  { transform: translateX(-22%) translateZ(0) rotateY(-30deg); opacity: 1; }
      82%  { transform: translateX(3px) translateZ(0) rotateY(8deg); opacity: 1; }
      100% { transform: translateX(0) translateZ(0) rotateY(0deg); opacity: 1; }
    }

    .tj-approach-content .title {
      opacity: 0;
      transform: translateY(60px);
    }

    .js-ready .tj-approach-item:nth-child(1).in-view .tj-approach-content .title {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 0.7s;
    }
    .js-ready .tj-approach-item:nth-child(2).in-view .tj-approach-content .title {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1.1s;
    }
    .js-ready .tj-approach-item:nth-child(3).in-view .tj-approach-content .title {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1.5s;
    }
    .js-ready .tj-approach-item:nth-child(4).in-view .tj-approach-content .title {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1.9s;
    }

    .tj-approach-content .desc {
      opacity: 0;
      transform: translateY(60px);
    }

    .js-ready .tj-approach-item:nth-child(1).in-view .tj-approach-content .desc {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1s;
    }
    .js-ready .tj-approach-item:nth-child(2).in-view .tj-approach-content .desc {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1.4s;
    }
    .js-ready .tj-approach-item:nth-child(3).in-view .tj-approach-content .desc {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 1.8s;
    }
    .js-ready .tj-approach-item:nth-child(4).in-view .tj-approach-content .desc {
      animation: textReveal 1.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
      animation-delay: 2.2s;
    }

    @keyframes textReveal {
      0%   { opacity: 0;  transform: translateY(45px); }
      100% { opacity: 1; transform: translateY(0); }
    }


