  .vd-wx{position:relative;background:#fff;scroll-margin-top:100px;overflow:hidden}
  /* drifting glow blobs */
  .vd-wx::before,.vd-wx::after{content:"";position:absolute;border-radius:50%;filter:blur(90px);opacity:.35;pointer-events:none;animation:vdwxFloat 14s ease-in-out infinite alternate}
  .vd-wx::before{width:380px;height:380px;background:#C6A15B;left:-100px}
  .vd-wx::after{width:420px;height:420px;background:#9A0064;opacity:.14;bottom:-120px;right:-120px;animation-delay:-6s}
  @keyframes vdwxFloat{to{transform:translate(60px,40px) scale(1.15)}}
  .vd-wx .container{position:relative;z-index:1}
  
  /* track */
  .vd-wx-track{position:relative;display:grid;grid-template-columns:repeat(4,1fr);column-gap:28px;margin-top:60px;padding-bottom:20px;align-items:start}
  .vd-wx-svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none}
  .vd-wx-path-bg{fill:none;stroke:#E4DFD6;stroke-width:2;stroke-dasharray:3 8;stroke-linecap:round}
  .vd-wx-path{fill:none;stroke:url(#vdwxGrad);stroke-width:3;stroke-linecap:round;filter:drop-shadow(0 0 6px rgba(154,0,100,.35))}
  .vd-wx-dot{fill:#9A0064;filter:drop-shadow(0 0 8px rgba(154,0,100,.7));opacity:0;transition:opacity .3s}
  
  /* staircase: each stage sits higher than the last */
  .vd-wx-item{position:relative;padding-top:34px;margin-top:calc((3 - var(--i)) * 56px)}
  .vd-wx-node{position:absolute;top:-9px;left:28px;width:18px;height:18px;border-radius:50%;background:#fff;border:2px solid #DAD5CB;z-index:2;transform:scale(.6);transition:transform .6s cubic-bezier(.34,1.56,.64,1),background .4s,border-color .4s}
  .vd-wx-node::after{content:"";position:absolute;inset:-2px;border-radius:50%;border:2px solid #C6A15B;opacity:0}
  .vd-wx-item.on .vd-wx-node{transform:scale(1);background:#C6A15B;border-color:#9A0064}
  .vd-wx-item.on .vd-wx-node::after{animation:vdwxPulse 2.4s ease-out infinite}
  @keyframes vdwxPulse{0%{transform:scale(1);opacity:.9}100%{transform:scale(3);opacity:0}}
  
  /* card */
  .vd-wx-card{position:relative;height:100%;padding:34px 26px 30px;border-radius:18px;background:linear-gradient(160deg,#fff,#FAF6EE);border:1px solid #EDE6D8;overflow:hidden;
    opacity:0;transform:translateY(60px) scale(.96);
    transition:opacity .9s ease,transform 1s cubic-bezier(.16,1,.3,1),box-shadow .4s,border-color .4s}
  .vd-wx-item.on .vd-wx-card{opacity:1;transform:none}
  .vd-wx-item.on .vd-wx-card:hover{transform:translateY(-8px);box-shadow:0 24px 50px -18px rgba(58,24,55,.35);border-color:#C6A15B}
  /* cursor spotlight */
  .vd-wx-card::before{content:"";position:absolute;inset:0;background:radial-gradient(260px circle at var(--mx,50%) var(--my,0%),rgba(198,161,91,.25),transparent 70%);opacity:0;transition:opacity .4s;pointer-events:none}
  .vd-wx-card:hover::before{opacity:1}
  /* gold bar that fills on reveal */
  .vd-wx-card::after{content:"";position:absolute;left:0;top:0;height:3px;width:100%;background:linear-gradient(90deg,#C6A15B,#9A0064);transform:scaleX(0);transform-origin:left;transition:transform 1.1s cubic-bezier(.65,0,.35,1) .35s}
  .vd-wx-item.on .vd-wx-card::after{transform:scaleX(1)}
  
  .vd-wx-icon{width:54px;height:54px;border-radius:14px;display:grid;place-items:center;background:#3A1837;color:#C6A15B;margin-bottom:20px;transition:transform .5s cubic-bezier(.34,1.56,.64,1),background .3s}
  .vd-wx-icon svg{width:26px;height:26px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:120;stroke-dashoffset:120;transition:stroke-dashoffset 1.4s ease .5s}
  .vd-wx-item.on .vd-wx-icon svg{stroke-dashoffset:0}
  .vd-wx-card:hover .vd-wx-icon{transform:rotate(-8deg) scale(1.1);background:#9A0064}
  
  .vd-wx-title{position:relative;font-size:20px;line-height:1.3;color:#3A1837;margin:0 0 14px;transition:color .3s}
  .vd-wx-card:hover .vd-wx-title{color:#9A0064}
  .vd-wx-desc{font-size:15px;line-height:1.75;color:var(--tj-color-text-body,#303030);margin:0}
  /* stagger text */
  .vd-wx-icon,.vd-wx-title,.vd-wx-desc{opacity:0;transform:translateY(20px);transition-property:opacity,transform,background}
  .vd-wx-item.on .vd-wx-icon,.vd-wx-item.on .vd-wx-title,.vd-wx-item.on .vd-wx-desc{opacity:1;transform:none}
  .vd-wx-icon{transition-duration:.8s;transition-delay:.25s}
  .vd-wx-title{transition-duration:.8s;transition-delay:.4s}
  .vd-wx-desc{transition-duration:.8s;transition-delay:.55s} 
  
  @media (max-width:1399px){.vd-wx-track{column-gap:20px}.vd-wx-card{padding:30px 20px 26px}.vd-wx-item{margin-top:calc((3 - var(--i)) * 40px)}}
  /* tablet / mobile: vertical path, no staircase */
  @media (max-width:991px){
    .vd-wx-track{grid-template-columns:1fr;row-gap:36px;padding-left:46px;margin-top:44px}
    .vd-wx-item{margin-top:0;padding-top:0}
    .vd-wx-node{top:34px;left:-46px}
  }
  @media (prefers-reduced-motion:reduce){
    .vd-wx::before,.vd-wx::after,.vd-wx-node::after{animation:none!important}
    .vd-wx-card,.vd-wx-icon,.vd-wx-title,.vd-wx-desc,.vd-wx-card::after,.vd-wx-icon svg{opacity:1!important;transform:none!important;transition:none!important;stroke-dashoffset:0!important}
  }


  /* === Vidhitra Footer v3 — matches Pentagram structure === */

  /* --- Top row --- */
  .tj-footer-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
    padding-bottom: 40px;
    flex-wrap: wrap;
  }
  .tj-footer-brand .footer-logo img { height: 50px; width: auto; margin-bottom: 14px; }
  .tj-footer-brand .tagline { max-width: 400px; font-size: 14px; line-height: 1.6; color: rgba(255, 255, 255, 0.55); margin: 0; }

  .tj-footer-socials { display: flex; gap: 10px; list-style: none; padding: 0; margin: 0; }
  .tj-footer-socials a {
    width: 36px; height: 36px; border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.25);
    display: flex; align-items: center; justify-content: center;
    color: #FFFFFF; transition: background 0.25s ease, border-color 0.25s ease;
  }
  .tj-footer-socials a:hover { background: #9A0064; border-color: #9A0064; }

  /* --- Pentagram-style stacked rows --- */
  .tj-footer-rows {
    border-top: 1px solid rgba(255, 255, 255, 0.15);
  }

  .tj-footer-row {
    display: flex;
    align-items: flex-start;
    gap: 40px;
    padding: 26px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  }

  .tj-row-label {
    flex: 0 0 240px;         /* fixed-width label column, like Pentagram's left labels */
    font-size: 15px;
    font-weight: 600;
    color: #FFFFFF;
  }

  .tj-row-content {
    flex: 1 1 auto;
  }

  /* Link rows wrap naturally — matches how Pentagram's right-side content
    isn't forced into rigid single-file columns */
  .tj-row-links {
    display: flex;
    flex-wrap: wrap;
    column-gap: 32px;
    row-gap: 10px;
  }
  .tj-row-links a {
    font-size: 14.5px;
    color: rgba(255, 255, 255, 0.8);
    white-space: nowrap;
  }
  .tj-row-links a:hover { color: #FFFFFF; text-decoration: underline; }

  /* Capabilities has 7 long items — let these wrap onto a fresh line as
    a natural flex-wrap, like Pentagram's own content column does */
  .tj-row-links-wide a { white-space: normal; max-width: 260px; }

  .tj-row-contact {
    display: flex;
    flex-wrap: wrap;
    gap: 24px;
    font-size: 14.5px;
  }
  .tj-row-contact a { color: rgba(255, 255, 255, 0.85); }
  .tj-row-contact a:hover { color: #FFFFFF; text-decoration: underline; }
  .tj-row-note { color: rgba(255, 255, 255, 0.5); }

