/* ==========================================================
   ABOUT PAGE — STICKY SUB-NAV (Bain-style page tab bar)
   The "About Us" label is hidden until the bar goes sticky —
   it only appears once the bar has pinned under the header.
   ========================================================== */
.vd-page-subnav {
  background: #ffffff;
  border-bottom: 1px solid rgb(0 0 0 / 11%);
   border-top: 1px solid rgb(0 0 0 / 11%);
  position: relative;
  z-index: 45;
  width: 100%;
}
.vd-page-subnav.is-sticky {
  position: fixed;
  left: 0;
  right: 0;
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
}
.vd-page-subnav-spacer { display: none; }
.vd-page-subnav-spacer.is-active { display: block; }
.vd-page-subnav-inner {
  display: flex;
  align-items: center;
  gap: 36px;
  padding: 0px 0;
}
.vd-page-subnav-title {
  display: none;
  color: #9A0064;
  white-space: nowrap;
  padding-right: 24px;
  border-right: 1px solid rgba(0,0,0,0.12);
  flex-shrink: 0;
  font-weight: 700;
}
.vd-page-subnav.is-sticky .vd-page-subnav-title {
  display: inline-block;
  animation: vdTitleFadeIn 0.4s ease;
}
@keyframes vdTitleFadeIn {
  from { opacity: 0; transform: translateX(-10px); }
  to   { opacity: 1; transform: translateX(0); }
}
.vd-page-subnav-tabs {
  display: flex;
  align-items: center;
  gap: 30px;
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-x: auto;
  scrollbar-width: none;
}
.vd-page-subnav-tabs::-webkit-scrollbar { display: none; }
.vd-page-subnav-tabs li { flex-shrink: 0; }
.vd-page-subnav-tabs a {
  display: inline-block;
  padding: 10px 1px 10px;
    font-family: "Graphik", Helvetica, sans-serif, Lucida Sans Unicode;
    font-size: .875rem; 
  letter-spacing: 0.04em;
  font-weight: bold;
  color: #999999;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color 0.25s ease, border-color 0.25s ease;
}
.vd-page-subnav-tabs a:hover,
.vd-page-subnav-tabs a.active {
  color: #9a0064;
  border-color: #c9a24b;
}

/* ==========================================================
   SCROLL-REVEAL SYSTEM — every section animates in its own way
   ========================================================== */
.vd-reveal {
  opacity: 0;
  transition: opacity 0.85s cubic-bezier(0.22,0.61,0.36,1),
              transform 0.85s cubic-bezier(0.22,0.61,0.36,1);
  transition-delay: var(--vd-delay, 0s);
}
.vd-reveal.is-visible { opacity: 1; transform: none !important; }
.vd-reveal--up     { transform: translateY(42px); }
.vd-reveal--left    { transform: translateX(-52px); }
.vd-reveal--right   { transform: translateX(52px); }
.vd-reveal--scale   { transform: scale(0.9); }
.vd-reveal--fade    { transform: translateY(0); }

/* Base section rhythm */
.vd-about-section {
  padding: 96px 0;
  scroll-margin-top: 140px;
  overflow: hidden;
}

.site-main > .tj-page-header {
  box-shadow:
inset 0 0 0 100vmax rgb(58 0 40 / 11%), inset 0 170px 150px -70px rgb(0 0 0 / 37%), inset 520px 0 380px -260px rgb(0 0 0 / 32%)
}


.ab-page .ab-vals__bg::after {
    background: linear-gradient(160deg, rgb(246 233 217 / 11%) 0%, rgb(255 255 255 / 40%) 50%, rgba(243, 223, 233, 0.9) 100%);
}